               "<style>body{font-family:Arial,sans-serif;max-width:600px;margin:50px auto;padding:20px;}"
               "input,button{padding:10px;margin:5px 0;width:100%;box-sizing:border-box;}"
               "button{background:#007bff;color:white;border:none;cursor:pointer;}"
               "button:hover{background:#0056b3;}.error{color:red;}.success{color:green;}"
               ".session-info{background:#f0f0f0;padding:15px;border-radius:5px;margin:20px 0;}</style>"
               "</head><body>";
    }

    string get_html_footer() {
        return "</body></html>";
    }

    void handle_login(int client_fd, const string& method, const string& path,
                     const string& headers, const string& body, const string& client_ip) {
        if (method == "GET") {
            string html = get_html_header("Login") +
                         "<h2>Secure Session Login</h2>"
                         "<form method='POST' action='/login'>"
                         "<input type='text' name='username' placeholder='Username' required>"
                         "<input type='password' name='password' placeholder='Password' required>"
                         "<button type='submit'>Login</button>"
                         "</form>" + get_html_footer();
            send_response(client_fd, 200, "OK", "text/html", html);
        } else if (method == "POST") {
            auto form = parse_form_data(body);
            string username = form["username"];
            string password = form["password"];

            // Simple authentication (in production, use proper password hashing)
            if (username == "admin" && password == "secret123") {
                string session_id = session_mgr.create_session(username, client_ip);
                string html = get_html_header("Login Success") +
                             "<div class='success'>Login successful!</div>"
                             "<div class='session-info'>"
                             "<p><strong>Session ID:</strong> " << session_id.substr(0, 16) << "...</p>"
                             "<p><strong>User:</strong> " << username << "</p>"
                             "<p><strong>IP:</strong> " << client_ip << "</p>"
                             "</div>"
                             "<a href='/dashboard'><button>Go to Dashboard</button></a>"
                             "<form method='POST' action='/logout' style='margin-top:20px;'>"
                             "<button type='submit' style='background:#dc3545;'>Logout</button>"
                             "</form>" + get_html_footer();

                vector<pair<string, string>> headers = {
                    {"Set-Cookie", "session_id=" + session_id + "; HttpOnly; Path=/; SameSite=Strict; Max-Age=1800"}
                };
                send_response(client_fd, 200, "OK", "text/html", html, headers);
            } else {
                string html = get_html_header("Login Failed") +
                             "<div class='error'>Invalid credentials</div>"
                             "<a href='/login'><button>Try Again</button></a>" + get_html_footer();
                send_response(client_fd, 401, "Unauthorized", "text/html", html);
            }
        }
    }

    void handle_dashboard(int client_fd, const string& method, const string& path,
                         const string& headers, const string& body, const string& client_ip) {
        string session_id = get_cookie_value(headers, "session_id");
        Session session;

        if (session_id.empty() || !session_mgr.validate_session(session_id, session)) {
            string html = get_html_header("Access Denied") +
                         "<div class='error'>Invalid or expired session. Please login.</div>"
                         "<a href='/login'><button>Login</button></a>" + get_html_footer();
            send_response(client_fd, 403, "Forbidden", "text/html", html);
            return;
        }

        auto now = system_clock::now();
        auto duration = duration_cast<minutes>(session.expires_at - now);
        string html = get_html_header("Dashboard") +
                     "<h2>Welcome, " + session.username + "!</h2>"
                     "<div class='session-info'>"
                     "<p><strong>Session ID:</strong> " << session.id.substr(0, 16) << "...</p>"
                     "<p><strong>Created:</strong> " << put_time(localtime(&system_clock::to_time_t(session.created_at)), "%Y-%m-%d %H:%M:%S") << "</p>"
                     "<p><strong>Expires in:</strong> " << duration.count() << " minutes</p>"
                     "<p><strong>IP Address:</strong> " << session.ip_address << "</p>"
                     "<p><strong>Active Sessions:</strong> " << session_mgr.active_sessions() << "</p>"
                     "</div>"
                     "<form method='POST' action='/logout'>"
                     "<button type='submit' style='background:#dc3545;'>Logout</button>"
                     "</form>" + get_html_footer();
        send_response(client_fd, 200, "OK", "text/html", html);
    }

    void handle_logout(int client_fd, const string& method, const string& path,
                      const string& headers, const string& body, const string& client_ip) {
        string session_id = get_cookie_value(headers, "session_id");
        if (!session_id.empty()) {
            session_mgr.destroy_session(session_id);
        }

        string html = get_html_header("Logged Out") +
                     "<div class='success'>You have been logged out successfully.</div>"
                     "<a href='/login'><button>Login Again</button></a>" + get_html_footer();

        vector<pair<string, string>> headers_out = {
            {"Set-Cookie", "session_id=; HttpOnly; Path=/; Max-Age=0"}
        };
        send_response(client_fd, 200, "OK", "text/html", html, headers_out);
    }

    void handle_request(int client_fd) {
        char buffer[4096] = {0};
        ssize_t bytes_read = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_read <= 0) {
            close(client_fd);
            return;
        }

        string request(buffer, bytes_read);
        string client_ip = get_client_ip(client_fd);

        // Parse request line
        size_t first_line_end = request.find("\r\n");
        string first_line = request.substr(0, first_line_end);
        size_t method_end = first_line.find(' ');
        size_t path_end = first_line.find(' ', method_end + 1);

        string method = first_line.substr(0, method_end);
        string path = first_line.substr(method_end + 1, path_end - method_end - 1);
        string version = first_line.substr(path_end + 1);

        // Parse headers
        size_t headers_end = request.find("\r\n\r\n");
        string headers = request.substr(0, headers_end);
        string body = (headers_end != string::npos) ? request.substr(headers_end + 4) : "";

        // Route handling
        if (path == "/" || path == "/login") {
            handle_login(client_fd, method, path, headers, body, client_ip);
        } else if (path == "/dashboard") {
            handle_dashboard(client_fd, method, path, headers, body, client_ip);
        } else if (path == "/logout") {
            handle_logout(client_fd, method, path, headers, body, client_ip);
        } else {
            string html = get_html_header("404") +
                         "<h2>404 - Not Found</h2>"
                         "<a href='/login'><button>Go Home</button></a>" + get_html_footer();
            send_response(client_fd, 404, "Not Found", "text/html", html);
        }

        close(client_fd);
    }

